    add(10, 'reasoning', 'multi-step', 'master', 'windmill',
        T('Castle Finale', 'Kemuncak Istana'),
        T('The king will crown a hero today! Solve three steps to prepare the castle.', 'Raja akan menabalkan seorang wira hari ini! Selesaikan tiga langkah untuk menyiapkan istana.'),
        T('Multi-step problems with area, money and sharing.', 'Masalah berbilang langkah dengan luas, wang dan perkongsian.'),
        'Crowny', T('Crowny tries on every crown in the castle.', 'Crowny mencuba setiap mahkota di istana.'),
        [steps([step(T('A banquet table seats 8 people. How many people sit at 9 tables?', 'Sebuah meja jamuan menempatkan 8 orang. Berapa orang yang duduk di 9 meja?'), 72, '9*8'),
                step(T('Each person eats 3 bread rolls. How many rolls are needed?', 'Setiap orang makan 3 biji roti. Berapa biji roti diperlukan?'), 216, '72*3'),
                step(T('A baker makes 24 rolls an hour. How many hours does the baker need?', 'Seorang tukang roti membuat 24 biji roti sejam. Berapa jam yang diperlukan tukang roti itu?'), 9, '216/24')],
               T('Find the people first, then the rolls.', 'Cari bilangan orang dahulu, kemudian bilangan roti.'), T('9 × 8 = 72, then 72 × 3 = 216, then 216 ÷ 24 = 9.', '9 × 8 = 72, kemudian 72 × 3 = 216, kemudian 216 ÷ 24 = 9.'), 'kk10a'),
         steps([step(T('A castle has 4 towers with 36 steps each. How many steps in all?', 'Sebuah istana mempunyai 4 menara dengan 36 anak tangga setiap satu. Berapa anak tangga kesemuanya?'), 144, '4*36'),
                step(T('A guard climbs 2 towers. How many steps does he climb?', 'Seorang pengawal mendaki 2 menara. Berapa anak tangga yang didakinya?'), 72, '2*36'),
                step(T('How many steps are left for the other guard to climb?', 'Berapa anak tangga yang tinggal untuk didaki pengawal yang lain?'), 72, '144-72')],
               T('Work out one tower at a time.', 'Kira satu menara pada satu masa.'), T('4 × 36 = 144, 2 × 36 = 72, then 144 − 72 = 72.', '4 × 36 = 144, 2 × 36 = 72, kemudian 144 − 72 = 72.'), 'kk10b'),
         steps([step(T('The king gives 5 coins to each of 12 knights. How many coins?', 'Raja memberikan 5 syiling kepada setiap seorang daripada 12 orang kesatria. Berapa syiling?'), 60, '5*12'),
                step(T('He also gives 40 coins to the cook. How many coins has he given in total?', 'Dia juga memberikan 40 syiling kepada tukang masak. Berapa jumlah syiling yang telah diberikannya?'), 100, '60+40'),
                step(T('The king had 250 coins. How many coins are left?', 'Raja mempunyai 250 syiling. Berapa syiling yang tinggal?'), 150, '250-100')],
               T('Add everything he gave away, then subtract.', 'Tambah semua yang diberikannya, kemudian tolak.'), T('5 × 12 = 60, then 60 + 40 = 100, then 250 − 100 = 150.', '5 × 12 = 60, kemudian 60 + 40 = 100, kemudian 250 − 100 = 150.'), 'kk10c')])
